      }
    ],
    "lacunas": [
      "As relações de precedência da ficha d_a70f não estão incluídas nos dados fornecidos; não é possível determinar se a redução da atividade emitir dossiê altera o término do marco final."
    ],
    "motivo": "O aviso reduz a duração de emitir dossiê, mas não há suporte para calcular o efeito dessa redução no término do projeto.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_d7254f",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "Faltam as relações de precedência necessárias para saber se a atividade reduzida controla o término ou se a alteração não afeta o marco final."
    ],
    "motivo": "A linha base é D12 e o aviso reduz uma duração, mas não se pode determinar se o término antecipa ou permanece igual.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base declarada fixa o custo em R$ 1.650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_d7254f",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "O custo recalculado do apoio depende do término novo, que não pode ser determinado sem as relações de precedência."
    ],
    "motivo": "O aditivo permite crédito da extensão não usada, mas o valor depende do término do projeto; as demais parcelas são fixas.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_d7254f",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "Sem determinar o término novo, não se determina a extensão recalculada do apoio nem a variação total do custo."
    ],
    "motivo": "O custo base é conhecido, mas a extensão creditável depende do término novo, que permanece indeterminado.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "O aviso reduz a duração de emitir dossiê de 3 para 1 dia e autoriza recalcular com crédito a extensão do apoio. As relações de precedência necessárias para avaliar o impacto no término não constam dos dados fornecidos; por isso não é possível fixar o término novo nem o custo recalculado."
}

